"use client";

import { Search } from "lucide-react";

import { Button } from "@/components/ui/button";

export function SearchButton() {
  return (
    <Button
      type="submit"
      className="
        h-12
        rounded-none
        px-8
        bg-primary
        hover:bg-primary/90
      "
    >
      <Search className="mr-2 h-4 w-4" />
      Pesquisar
    </Button>
  );
}